<script setup>
import {computed} from 'vue';import AccountIcon from './AccountIcon.vue';import AccountResource from './AccountResource.vue';
const props=defineProps({profile:Object,addresses:Object});defineEmits(['retry']);
const initial=computed(()=>Array.from(props.profile.data?.name.trim()||'?')[0].toLocaleUpperCase('vi-VN'));
const checklist=computed(()=>[{label:'Họ tên',done:!!props.profile.data?.name.trim()},{label:'Email đã xác thực',done:props.profile.data?.emailVerified===true},{label:'Số điện thoại',done:!!props.profile.data?.phone?.trim()},{label:'Địa chỉ mặc định',done:props.addresses.data?props.addresses.data.some(a=>a.isDefault):null}]);
</script>
<template><section class="bm-buyer-account-card bm-buyer-account-summary" aria-label="Hồ sơ tài khoản"><AccountResource :resource="profile" label="hồ sơ" @retry="$emit('retry')"><div class="bm-buyer-account-identity"><span class="bm-buyer-account-avatar" aria-hidden="true">{{ initial }}</span><div class="bm-buyer-account-identity-copy"><h2>{{ profile.data.name }}</h2><p><AccountIcon name="mail"/>{{ profile.data.email }}</p><span class="bm-buyer-account-badge" :class="{'bm-buyer-account-badge-muted':!profile.data.emailVerified}"><AccountIcon :name="profile.data.emailVerified?'check':'info'"/>{{ profile.data.emailVerified?'Đã xác thực email':'Chưa xác thực email' }}</span><RouterLink v-if="!profile.data.emailVerified" class="bm-buyer-account-text-link" to="/verify-email">Tiếp tục xác thực email</RouterLink><p class="bm-buyer-account-member"><AccountIcon name="sprout"/>Thành viên BonsaiMarket</p><p v-if="profile.data.bio" class="bm-buyer-account-bio">{{ profile.data.bio }}</p></div></div><div class="bm-buyer-account-summary-actions"><RouterLink class="button button-primary" to="/profile?section=edit"><AccountIcon name="edit"/>Chỉnh sửa hồ sơ</RouterLink><RouterLink class="button button-outline" to="/profile?section=addresses"><AccountIcon name="pin"/>Quản lý địa chỉ</RouterLink></div><div class="bm-buyer-account-completion"><h3>Hồ sơ của bạn</h3><ul><li v-for="item in checklist" :key="item.label"><AccountIcon :name="item.done?'check':'info'"/><span>{{ item.label }}</span><small>{{ item.done===null?'Chưa xác định':item.done?'Đã có':'Cần bổ sung' }}</small></li></ul><p>Bổ sung thông tin để thuận tiện mua hàng.</p></div></AccountResource></section></template>
